$ErrorActionPreference = 'Stop'
# Rebuild the single-file distribution after editing NexusUI/*.lua.
$projectDir = $PSScriptRoot
$bundleDir = Join-Path $projectDir 'dist'
[System.IO.Directory]::CreateDirectory($bundleDir) | Out-Null
$parts = [System.Collections.Generic.List[string]]::new()
$parts.Add(@'
-- NexusUI | MIT License | generated by build.ps1
-- Run on the Roblox client. Returns the NexusUI API.
local factories, cache = {}, {}
local function import(name)
    if cache[name] ~= nil then return cache[name] end
    assert(factories[name], 'NexusUI: missing module ' .. name)
    local value = factories[name]()
    cache[name] = value
    return value
end
'@)
foreach ($moduleName in @('Theme', 'Utility', 'Elements', 'Window', 'Init')) {
    $source = [System.IO.File]::ReadAllText((Join-Path $projectDir "NexusUI\$moduleName.lua"))
    $source = [regex]::Replace($source, 'require\(script\.Parent\.(\w+)\)', 'import("$1")')
    $parts.Add("factories.$moduleName = function()`n$source`nend")
}
$parts.Add('return import("Init")')
$bundle = $parts -join "`n`n"
if ($bundle -match 'require\(script\.Parent\.') { throw 'Unresolved module reference' }
[System.IO.File]::WriteAllText((Join-Path $bundleDir 'NexusUI.lua'), $bundle, [System.Text.UTF8Encoding]::new($false))
Write-Output 'Built dist/NexusUI.lua'
